using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;
namespace ParkingLotEnvironment.CloudPilot {public static class PorterReferenceRunner {
 const string Source="Assets/_Parkside/Scenes/ParklingLot.unity",W=PorterReferenceBuilder.W,Trial=W+"/PorterReferenceParkingLot.unity",Expected="ab4d65d1fc883ec10060bdba0502642bcf7eaa8573e0fdfb4478b83283fc213f";
 static string output,trialHash;static GameObject root;static Camera cam;static int frame=-1;static Vector3 pos;static Quaternion rot;
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP")||Hash(Source)!=Expected)throw new Exception("STOP or source changed");}
 static void Args(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-collabOutput");output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(output);}
 public static void BuildAndCapture(){try{Check();Args();if(File.Exists(Trial))throw new Exception("Candidate exists");EditorSceneManager.OpenScene(Source);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");PorterReferenceBuilder.Apply(root,output);ContextBuilder.Validate(root,output);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Trial);BeginCapture();}catch(Exception e){Fail(e);}}
 static void BeginCapture(){trialHash=Hash(Trial);cam=root.GetComponentInChildren<Camera>();cam.enabled=false;pos=cam.transform.position;rot=cam.transform.rotation;EditorApplication.update+=CaptureTick;}
 static Quaternion Look(Vector3 from,Vector3 at){return Quaternion.LookRotation(at-from);}
 static void CaptureTick(){try{Check();if(frame<0)Render(null,pos,rot,960,540);else if(frame==0){var p=new Vector3(-.3f,1.75f,-7);Render("porter-close.png",p,Look(p,new Vector3(-5,1,-4.5f)),2560,1440);}else if(frame==1){var p=new Vector3(-5.6f,1.65f,-.65f);Render("porter-side.png",p,Look(p,new Vector3(-5.6f,1,-4.5f)),1920,1080);}else if(frame==2){var p=new Vector3(.7f,2.8f,-17.5f);Render("parking-context.png",p,Look(p,new Vector3(.7f,1.2f,-6.7f)),2560,1440);}else{EditorApplication.update-=CaptureTick;if(Hash(Trial)!=trialHash)throw new Exception("Candidate changed");File.WriteAllText(output+"/capture-complete.txt","Photo-referenced candidate; 2 native1440p +1 native1080p; original baked lighting preserved because all changed truck surfaces are dynamic and do not contribute baked GI. Reflection bake/promotion pending. SHA="+trialHash);EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name,Vector3 p,Quaternion q,int w,int h){var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGBHalf){antiAliasing=1};var old=cam.targetTexture;var active=RenderTexture.active;try{rt.Create();cam.targetTexture=rt;cam.transform.SetPositionAndRotation(p,q);cam.Render();if(name!=null){RenderTexture.active=rt;var im=new Texture2D(w,h,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,w,h),0,0);im.Apply();File.WriteAllBytes(output+"/"+name,im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}}finally{cam.targetTexture=old;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 static void Fail(Exception e){EditorApplication.update-=CaptureTick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
